(()=>{const input=document.querySelector('#reduce'),mq=matchMedia('(prefers-reduced-motion:reduce)'),listeners=[];let external=false;const reduced=()=>!!input?.checked||mq.matches||external;function preference(){document.body.classList.toggle('reduced',reduced());listeners.forEach(fn=>fn(reduced()))}function fit(){const wrap=document.querySelector('.phone-wrap');if(!wrap)return;const studio=new URLSearchParams(location.search).has('studio');document.body.classList.toggle('studio',studio);const scale=Math.min(1,(innerWidth-(studio?0:20))/375,studio?innerHeight/812:1);wrap.style.width=375*scale+'px';wrap.style.height=812*scale+'px';wrap.querySelector('.phone').style.transform='scale('+scale+')';wrap.querySelector('.phone').style.transformOrigin='top left'}input?.addEventListener('change',preference);mq.addEventListener('change',preference);addEventListener('resize',fit);addEventListener('message',e=>{if(e.source!==parent||(location.protocol!=='file:'&&e.origin!==location.origin))return;if(['motion-prefs','motion-preference'].includes(e.data?.type)){external=!!e.data.reduced;preference()}if(['reset','reset-demo'].includes(e.data?.type))reset()});function reset(){dispatchEvent(new Event('room-reset'))}document.querySelector('#reset')?.addEventListener('click',reset);window.room={reduced,onPreference:fn=>listeners.push(fn),announce:s=>{const o=document.querySelector('#state');if(o)o.textContent=s;parent.postMessage({type:'demo-state',state:s},'*')}};fit();preference()})();
